---@class OverseaManageMenuSettingDialog
local OverseaManageMenuSettingDialog = Class("OverseaManageMenuSettingDialog")
local MaidCoffeeMgr = import('Game.MaidCoffee.MaidCoffeeMgr')
local MaidCoffeeConstants = import("Game.MaidCoffee.MaidCoffeeConstants")
local TabCellPath = "Game.MaidCoffee.MaidCoffeeUIDialog.Cell.OverseaManageMenuSettingTabCell"
local AfterPutOnPath = "Game.MaidCoffee.MaidCoffeeUIDialog.OverseaManageMenuSettingPutNode"
local TodayMenuCellPath = "Game.MaidCoffee.MaidCoffeeUIDialog.Cell.OverseaManageMenuSettingDoubleMenuCell"
local FoodTypeNodePath = "Game.MaidCoffee.MaidCoffeeUIDialog.Cell.OverseaManageMenuSettingFoodTypeCell"
local LeftCellPath = "Game.MaidCoffee.MaidCoffeeUIDialog.Cell.OverSeaManageSettingLeftCell"
local CalculationPath = "Game.MaidCoffee.MaidCoffeeUIDialog.OverseaManageSettingCalculationNode"
local MenuCount = 3 --套餐数量
