function OverseaManageMenuSettingDialog:__init()

end

function OverseaManageMenuSettingDialog:Awake()
    self.preSelIndex = 1
    self.isFirst = true
    self.curFood = {}
    self:InitTabNode()
    self:InitNodeEnv()
    self:AddUIClick()
    self:AddEventListener()
    KTool.SetActive(self.SidePullMenuNode.gameObject,false)
    local component = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.MaidCoffeeComponent)
    local cafeLevel = component:GetMaidCoffeeLevel()
    local settingVo = CfUtils.GetCfVo(AutoIds.IdSetting3033, "MaidCoffeeManagerSettingVo", 50)
    KTool.SetActive(self.FontStyleButton.gameObject,false)
    if settingVo then
        local needLevel = checkNumber(settingVo.num)
        if cafeLevel >= needLevel then
            KTool.SetActive(self.FontStyleButton.gameObject,true)
        end
    end
    URPCameraController:SetMainCameraActive(true)
end

function OverseaManageMenuSettingDialog:AddEventListener()
    self.refreshEvent = Events.AddListener(Constants.EventNames.REFRESH_MAID_COFFEE_DATA,Bind(self,self.OnRefreshEvent))
    self.quickSaleEvent =  Events.AddListener(Constants.EventNames.MaidCoffeeQuickSaleSuccess,Bind(self,self.OnQuickSaleCallBack))
end

function OverseaManageMenuSettingDialog:RemoveEventListener()
    if self.refreshEvent then
        Events.RemoveListener(Constants.EventNames.REFRESH_MAID_COFFEE_DATA,self.refreshEvent)
        self.refreshEvent = nil
    end

    if self.quickSaleEvent then
        Events.RemoveListener(Constants.EventNames.MaidCoffeeQuickSaleSuccess,self.quickSaleEvent)
        self.quickSaleEvent = nil
    end
end

function OverseaManageMenuSettingDialog:InitNodeEnv()
    self:InitTodayMenu()
    self:InitFoodTypeNode()
    self:InitComponent()
end

function OverseaManageMenuSettingDialog:InitComponent()
    if self.AfterPutOn then
        local env = CfUtils.GetLuaScr(self.AfterPutOn, AfterPutOnPath)
        if env then
            env:SetCallBack(Bind(self,self.OnPutOffCallBack))
            self.afterPutOnEnv = env
        end
    end

    if self.CalculationNode then
        local env = CfUtils.GetLuaScr(self.CalculationNode,CalculationPath)
        if env then
            self.calculationEnv = env
        end
    end

    if self.EmptyNode then
        local env = CfUtils.GetLuaScr(self.EmptyNode,"Game.Behaviours.EmptyNodeMB")
        if env then
            self.emptyNodeEnv = env
        end
    end
end

function OverseaManageMenuSettingDialog:AddUIClick()
    SetButtonAction(self.FontStyleButton.gameObject,Bind(self,self.OnQuickAddBtnClick))
    SetButtonAction(self.BtnPutOn.gameObject,Bind(self,self.OnPutOnBtnClick))
    SetButtonAction(self.BtnRecommend.gameObject,Bind(self,self.OnBtnRecommendClick))
    SetButtonAction(self.BtnGetRecipe.gameObject,Bind(self,self.OnBtnGetRecipeClick))
end

function OverseaManageMenuSettingDialog:InitTodayMenu()
    self.todayMenuEnv = {}
    for i = 1, TodayFoodCount do
        local node = self["BtnRecipesNode"..i]
        if node then
            local env = CfUtils.GetLuaScr(node,TodayMenuCellPath)
            self.todayMenuEnv[i] = env
        end
    end
end

function OverseaManageMenuSettingDialog:InitFoodTypeNode()
    self.foodItemEnv = {}
    for i = 1, FoodItemCount do
        local node = self["FoodTypeNode"..i]
        if node then
            local env = CfUtils.GetLuaScr(node,FoodTypeNodePath)
            env:SetCallBack(Bind(self,self.OnAddBtnClick),true)
            self.foodItemEnv[i] = env
        end
    end
end

function OverseaManageMenuSettingDialog:InitTabNode()
    self.menuVo = {}
    for i = 1, MenuCount do
        local _, isLock = component:GetIsLockedAndVolume(i)
        local data = {vo = MaidCoffeeUtils.GetMaidCoffeeMenuVo(i) , isLock = isLock }
        self.menuVo[i] = data
    end

    if not self.TabScrollView.IsListViewInit then
        self.TabScrollView:InitListView(MenuCount, Bind(self, self.OnRefreshIndex))
    else
        for i = 1 , MenuCount do
            local newItem =  self.TabScrollView:GetShownItemByItemIndex(i - 1)
            if not isNull(newItem) then
                local tableCellEnv = CfUtils.GetLuaScr(newItem, TabCellPath)
                tableCellEnv:SetCallBack(Bind(self,self.OnTabCellClick))
                tableCellEnv:RefreshUI(i,self.preSelIndex,self.menuVo[i])
            end
        end
    end
end

function OverseaManageMenuSettingDialog:OnRefreshEvent()
    if not isNull(self.curSelectIndex) then
        local tempIndex = self.curSelectIndex
        self.curSelectIndex = nil
        self:OnTabCellClick(tempIndex)
        GameUtils.Toast(localize("日期更新，推荐食谱已变更"))
    end
end

function OverseaManageMenuSettingDialog:OnRefreshIndex(listView,index)
    local cell = listView:NewListViewItem(ItemCell)
    local tableCellEnv = CfUtils.GetLuaScr(cell, TabCellPath)
    tableCellEnv:SetCallBack(Bind(self,self.OnTabCellClick))
    tableCellEnv:RefreshUI(index + 1,self.preSelIndex,self.menuVo[index + 1])
    return cell
end

function OverseaManageMenuSettingDialog:OnTabCellClick(index)
    if self.curSelectIndex ~= nil and self.curSelectIndex == index then
        return
    end
    self:RefreshShow(index)
    self:RefreshAllTabSellState()
end

function OverseaManageMenuSettingDialog:RefreshAllTabSellState()
    for i = 1 , MenuCount do
        local newItem =  self.TabScrollView:GetShownItemByItemIndex(i - 1)
        if not isNull(newItem) then
            local tableCellEnv = CfUtils.GetLuaScr(newItem, TabCellPath)
            tableCellEnv:RefreshSellState()
        end
    end
end

function OverseaManageMenuSettingDialog:RefreshShow(index)
    ---选中的格子清掉
    self.curSlot = nil
    self.curFood = {}
    ---不能同时播放 第一次进场不能播
    if not self.isFirst then
        self.Root:Play("OverseaManageMenuSettingDialogSwitch")
    end
    if  self.isFirst then
        self.isFirst = false
    end
    self.calculationEnv:SetStatus(false)
    self:TabDoSelect(self.curSelectIndex)
    self.curSelectIndex = index
    self:RefreshSaleShow()
    self:RefreshBtnStatus()
end


function OverseaManageMenuSettingDialog:OnPutOffCallBack()
    self:RefreshTabSellState()
    self:RefreshAllTabSellState()
    ---判断当前套餐是否在售卖
    local menuInfo = component:GetCurIndexMenuInfo(self.curSelectIndex)
    local isSell = menuInfo ~= nil and  menuInfo:IsSell() or false
    KTool.SetActive(self.BeforePutOn.gameObject,not isSell)
    KTool.SetActive(self.AfterPutOn.gameObject,isSell)
    self.Container:Play("OverseaManageMenuSettingDialog_Default")
    self:RefreshPutOnInfo(menuInfo)
    local isInActivity = self:IsInActivity()
    KTool.SetActive(self.UPInstructionsSell.gameObject,isInActivity)
end

function OverseaManageMenuSettingDialog:OnQuickSaleCallBack()
    ---选中的格子清掉
    self.curSlot = nil
    self.curFood = {}
    self.calculationEnv:SetStatus(false)
    self:RefreshSaleShow()
    self:RefreshBtnStatus()
    self:RefreshAllTabSellState()
end
---上架成功回调
function OverseaManageMenuSettingDialog:OnPutOnSuccess()
    self.curSlot = nil
    self:RefreshTabSellState()
    --self:RefreshSaleShow()
    local menuInfo = component:GetCurIndexMenuInfo(self.curSelectIndex)
    local isSell = menuInfo ~= nil and  menuInfo:IsSell() or false
    KTool.SetActive(self.BeforePutOn.gameObject,not isSell)
    KTool.SetActive(self.AfterPutOn.gameObject,isSell)
    self.Container:Play("OverseaManageMenuSettingDialog_Arrive")
    self.afterPutOnEnv:RefreshShowInfo(menuInfo,self.curSelectIndex,"OverseaManegeSelectFoodTypeNodeContent_Arrive")
    local isInActivity = self:IsInActivity()
    KTool.SetActive(self.UPInstructionsSell.gameObject,isInActivity)
end

function OverseaManageMenuSettingDialog:RefreshSaleShow()
    local data = self.menuVo[self.curSelectIndex]
    KTool.SetActive(self.Empty.gameObject,data.isLock)
    local bgImg = MaidCoffeeConstants.BgImage[1]
    if  data.isLock then
        KTool.SetActive(self.BeforePutOn.gameObject,false)
        KTool.SetActive(self.AfterPutOn.gameObject,false)
        local lockDes = GameUtils.GetUnlockDescr(data.vo.unlockType, data.vo.unlockNum)
        self.emptyNodeEnv:SetText(lockDes)
        self.Container:Play("OverseaManageMenuSettingDialog_Default")
        self.afterPutOnEnv:StopBulletCo()
    else
        ---判断当前套餐是否在售卖
        local menuInfo = component:GetCurIndexMenuInfo(self.curSelectIndex)
        local isSell = menuInfo ~= nil and  menuInfo:IsSell() or false
        KTool.SetActive(self.BeforePutOn.gameObject,not isSell)
        KTool.SetActive(self.AfterPutOn.gameObject,isSell)
        bgImg = isSell and MaidCoffeeConstants.BgImage[2] or MaidCoffeeConstants.BgImage[1]
        if isSell then
            self.Container:Play("OverseaManageMenuSettingDialog_ArriveDefault")
            self.afterPutOnEnv:RefreshShowInfo(menuInfo,self.curSelectIndex,"OverseaManegeSelectFoodTypeNodeContent_Default")
        else
            self.Container:Play("OverseaManageMenuSettingDialog_Default")
            self:RefreshPutOnInfo(menuInfo)
            self.afterPutOnEnv:StopBulletCo()
        end
    end
    local isInActivity = self:IsInActivity()
    KTool.SetActive(self.UPInstructionsSell.gameObject,isInActivity)
    CfUtils.FillImage(self.ImgBg,bgImg)
end

function OverseaManageMenuSettingDialog:IsInActivity()
    local component = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.MaidCoffeeComponent)
    local homeDojo = component:GetMaidCoffeeHomeDoJo()
    local isInActivity = homeDojo:IsActivity()
    return isInActivity
end

function OverseaManageMenuSettingDialog:RefreshPutOnInfo()
    KTool.SetActive(self.SidePullMenuNode.gameObject,false)
    KTool.SetActive(self.CalculationNode.gameObject,false)
    for i = 1, #self.foodItemEnv do
        self.foodItemEnv[i]:InitFoodItem(self.curSelectIndex , i)
    end
    --- 更新一下今日双倍
    self:RefreshDoubleMenuInfo()
end

function OverseaManageMenuSettingDialog:RefreshDoubleMenuInfo()
    for i = 1, #self.todayMenuEnv do
        local doubleData = component:GetDoubleMenuData(self.curSelectIndex,i)
        if doubleData then
            self.todayMenuEnv[i]:RefreshShow(doubleData)
        end
    end

end
---@param index integer @ 表示点击的是那个格子通过日期获取到售卖组 然后再取到当前套餐当前格子的售卖列表
function OverseaManageMenuSettingDialog:RefreshLeftList(index)
    self.leftListShowVos = MaidCoffeeMgr:GetInstance():GetMenuNodeVos(self.curSelectIndex,index)
    local recommendData = component:GetDoubleMenuData(self.curSelectIndex,index)
    if #self.leftListShowVos > 0  then
        local maidCoffeePlayerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.MaidCoffeePlayerComponent)
        table.sort(self.leftListShowVos,function(a,b)
            local isRecommendA = a.refId == recommendData.recipeId and 2 or 1
            local isRecommendB = b.refId == recommendData.recipeId and 2 or 1
            if isRecommendA == isRecommendB then
                local aIsDouble = component:IsMenuDouble(self.curSelectIndex,self.curSlot,a.refId) and 2 or 1
                local bIsDouble = component:IsMenuDouble(self.curSelectIndex,self.curSlot,b.refId) and 2 or 1
                if aIsDouble == bIsDouble then
                    local recipeDojoA = maidCoffeePlayerComponent:GetRecipeDoJoById(a.refId)
                    local recipeDojoB = maidCoffeePlayerComponent:GetRecipeDoJoById(b.refId)
                    if recipeDojoA.rating == recipeDojoB.rating then
                        local priceA = a:GetPrice(recipeDojoA.rating)
                        local priceB = b:GetPrice(recipeDojoB.rating)
                        if priceA == priceB then
                            return a.refId < b.refId
                        else
                            return priceA > priceB
                        end
                    else
                        return recipeDojoA.rating > recipeDojoB.rating
                    end
                else
                    return aIsDouble > bIsDouble
                end
            else
                return isRecommendA > isRecommendB
            end
        end)
        local isRecommendIn = self:isRecommendDataIn(recommendData.recipeId)
        if not isRecommendIn then
            table.insert(self.leftListShowVos,1,{refId = recommendData.recipeId})
        end
        self:RefreshGridView()
    else
        local canGet = self:IsCanGet(recommendData.recipeId)
        if canGet then
            table.insert(self.leftListShowVos,{refId = recommendData.recipeId})
        end
        self:RefreshGridView()
    end
    KTool.SetActive(self.EmptyRecipe.gameObject,#self.leftListShowVos == 0)
    KTool.SetActive(self.MenuNodeList.gameObject,#self.leftListShowVos > 0)
end

function OverseaManageMenuSettingDialog:RefreshGridView()
    if self.MenuNodeList then
        if not self.MenuNodeList.IsListViewInit then
            self.MenuNodeList:InitListView(#self.leftListShowVos, Bind(self, self.OnRefreshMenuNodeIndex))
        else
            GameUtils.ReloadData(self.MenuNodeList, #self.leftListShowVos)
            self.MenuNodeList:MovePanelToItemIndex(0,0)
        end
    end
end

function OverseaManageMenuSettingDialog:isRecommendDataIn(recipeId)
    for i, v in pairs(self.leftListShowVos) do
        if v.refId == recipeId then
            return true
        end
    end
    return false
end

function OverseaManageMenuSettingDialog:IsCanGet(refId)
    local foodVo = GoodsConfMgr:GetInstance():GetGoodsVoById(refId)
    if not isNull(foodVo) then
        if isSet(foodVo, "jumpAway") and table.count(foodVo.jumpAway) > 0 then
            local goodsConfMgr = GoodsConfMgr:GetInstance()
            local row = goodsConfMgr:GetJumpModuleRow(foodVo.jumpAway[1])
            local canJump = goodsConfMgr:CheckIsCanJump(row,false)
            if canJump then
                if isSet(foodVo,"jumpParameter") then
                    local type = GoodsUtils.GetIdType(foodVo.jumpParameter[1], Constants.IDArea.Quests)
                    if type == Constants.IDType.QuestRegion then
                        local ActionUtils = import('Game.UI.FightReady.UIMainChapter.ActionUtils')
                        local isUnLock =  ActionUtils.IsUnlockRegionQuest(foodVo.jumpParameter[1])
                        if isUnLock then
                            return true
                        end
                    else
                        local canJump = goodsConfMgr:CheckIsCanJump(row,false)
                        if canJump then
                            return true
                        end
                    end
                else
                    local canJump = goodsConfMgr:CheckIsCanJump(row,false)
                    if canJump then
                        return true
                    end
                end
            end
        end
    end
    return false
end

function OverseaManageMenuSettingDialog:OnBtnGetRecipeClick()
    if #self.leftListShowVos > 0 then return end
    local maidCoffeeHomeDojo =  component:GetMaidCoffeeHomeDoJo()
    local tableIndex = maidCoffeeHomeDojo:GetSaleType(self.curSelectIndex,self.curSlot)
    UIModule.OpenDialog({ id = Constants.UITypeIds.UIMaidCoffeeCookingMainDialog, parameters = { type = MaidCoffeeConstants.CookingType.Cooking,tableIndex = tableIndex } })
end

function OverseaManageMenuSettingDialog:OnRefreshMenuNodeIndex(listView,index)
    if index < 0 or index >= #self.leftListShowVos then
        return
    end
    local cell = listView:NewListViewItem(ItemCell)
    local tableCellEnv = CfUtils.GetLuaScr(cell, LeftCellPath)
    tableCellEnv:SetCallBackAndIndex(Bind(self,self.OnLeftFoodCellClick),index + 1)
    local haveSelectData = self.curFood[self.curSlot]
    tableCellEnv:RefreshUI(self.leftListShowVos[index + 1])
    tableCellEnv:SetIsDouble(self.curSelectIndex,self.curSlot)
    tableCellEnv:RefreshSelect(haveSelectData)
    return cell
end

function OverseaManageMenuSettingDialog:OnLeftFoodCellClick(index)
    local data = self.leftListShowVos[index]
    if self.curFood[self.curSlot] and self.curFood[self.curSlot].refId == data.refId then
        return
    end
    self.foodItemEnv[self.curSlot]:SetItemShow(data)
    self.foodItemEnv[self.curSlot]:PlayAniByName("OverseaManegeSelectFoodTypeNodeContent_Go")
    self.todayMenuEnv[self.curSlot]:SetIsMatch(data)
    ---这里要存一下选择的食物  为计算做准备
    self.curFood[self.curSlot] = data
    self:LeftFoodCellDoSelect()
    ---刷新一下价格显示
    self:RefreshCalculationNode(true)
end

function OverseaManageMenuSettingDialog:LeftFoodCellDoSelect()
    ---有可能没有显示左侧列表
    if isNull(self.leftListShowVos) then return end
    for i, v in pairs(self.leftListShowVos) do
        local cell = self.MenuNodeList:GetShownItemByItemIndex(i - 1)
        if cell then
            local tableCellEnv = CfUtils.GetLuaScr(cell, LeftCellPath)
            local haveSelectData = self.curFood[self.curSlot]
            tableCellEnv:RefreshSelect(haveSelectData)
        end
    end
end

function OverseaManageMenuSettingDialog:TabDoSelect(index)
    if not isNull(index) then
        local newItem =  self.TabScrollView:GetShownItemByItemIndex(index - 1)
        if not isNull(newItem) then
            local tableCellEnv = CfUtils.GetLuaScr(newItem, TabCellPath)
            tableCellEnv:DoSelect()
        end
    end
end

function OverseaManageMenuSettingDialog:OnFocus(focus)
    if focus then
        GameUtils.RefreshTopGoods(Constants.UITypeIds.UIMaidCoffeeMenuSettingDialog)
        if not isNull(self.curSlot) then
            self:RefreshGridView()
            for i, v in pairs(self.foodItemEnv) do
                if not isNull(self.curFood[i]) then
                    self.foodItemEnv[i]:SetItemShow(self.curFood[i])
                end
            end
            self:RefreshCalculationNode(true)
        end
    end
end

function OverseaManageMenuSettingDialog:OnShow()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        xTry(function()
            URPCameraController:SetMainCameraActive(false)
            self.Root:Play("OverseaManageMenuSettingDialog_Go")
            MaidCoffeeUtils.MaidCoffeeSetMouseMode(Constants.CameraControlMode.None)
        end)
    end))
