end

function OverseaManageMenuSettingDialog:OnInitialize()
    URPCameraController.alwaysShowSceneRT = true
end

function OverseaManageMenuSettingDialog:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        xTry(function()
            self.controller = nil --删除lua层引⽤到的c#对象否则不会产⽣c# gc回收到对象
            self:RemoveEventListener()
            self:Delete()
            self = nil --lua层的gc需要    
        end)
    end))
    return coWait
end

function OverseaManageMenuSettingDialog:__delete()
    self.controller = nil
    self.curFood = nil
end

---click start--------------------------------
function OverseaManageMenuSettingDialog:OnPutOnBtnClick()
    local needFood = component:GetNeedPutOnFoodCount(self.curSelectIndex)
    if #self.curFood < needFood then
        GameUtils.Toast(localize("填充满所有食谱位置才可以上架套餐"))
        return
    end
    local menuId = self.curSelectIndex
    local recipes = {}
    for i, v in pairs(self.curFood) do
        recipes[i] = v.refId
    end
    local sellNum = tonumber(self.calculationEnv.curSellNum) ~= 0 and tonumber(self.calculationEnv.curSellNum) or 1
    local goodsId = MaidCoffeeUtils.GetMaidCoffeeManagerSettingVo(7).num
    local _,costSign,_,maxSellNum = component:CalculationMenuPrice(self.curSelectIndex,self.curFood)
    if maxSellNum >= sellNum then
        GameUtils.Request(Interfaces.MaidCoffeeMenuSubmit, { menuId = menuId,recipes = table.serialize(recipes),saleNum = sellNum }, function(request, response)
            if checkInt(response.errCode) == 0 then
                GoodsUtils.DrawRewards({[1] = { goodsId = goodsId, num = -(costSign * sellNum)} }, true)
                local maidCoffeeHomeDojo = component:GetMaidCoffeeHomeDoJo()
                maidCoffeeHomeDojo:UpdateMenuData(self.curSelectIndex,response.data.menu)
                self.curFood = {}
                --component:RefreshMenuRedPoint()
                self:OnPutOnSuccess()
            end
        end)
    else
        GameUtils.Toast(localize("当前金币不足"))
    end
end

function OverseaManageMenuSettingDialog:OnBtnRecommendClick()
    UIModule.OpenDialog({ id = Constants.UITypeIds.UIMaidCoffeeRecommend, parameters = {
        curIndex = self.curSelectIndex,curData = self.curFood
    }})
end

function OverseaManageMenuSettingDialog:RefreshTabSellState()
    local newItem =  self.TabScrollView:GetShownItemByItemIndex(self.curSelectIndex - 1)
    if not isNull(newItem) then
        local tableCellEnv = CfUtils.GetLuaScr(newItem, TabCellPath)
        tableCellEnv:RefreshSellState()
    end
end

function OverseaManageMenuSettingDialog:OnQuickAddBtnClick()
    ---@type MaidCoffeeComponent
    self.curFood = component:GetHighPriceFoodByIndex(self.curSelectIndex)
    self:RefreshCalculationNode(true)
    self:LeftFoodCellDoSelect()
    for i, v in pairs(self.curFood) do
        self.foodItemEnv[i]:OnSelect()
        self.foodItemEnv[i]:SetItemShow(v)
        self.foodItemEnv[i]:PlayAniByName("OverseaManegeSelectFoodTypeNodeContent_Go")
        self.todayMenuEnv[i]:SetIsMatch(v)
    end
end

function OverseaManageMenuSettingDialog:OnAddBtnClick(index)
    if self.curSlot ~= nil and self.curSlot == index then
        return
    end
    if not self.curSlot then
        KTool.SetActive(self.SidePullMenuNode.gameObject,true)
        KTool.SetActive(self.UPInstructionsSell.gameObject,false)
        local isInActivity = self:IsInActivity()
        KTool.SetActive(self.UPInstructions.gameObject,isInActivity)
        self.Root:Play("OverseaManageMenuSettingDialog_PullMenu")
    else
        self.Root:Play("OverseaManageMenuSettingDialog_MenuSwitch")
    end
    self:FoodTypeDoSelect()
    self.curSlot = index
    self:RefreshLeftList(index)
end

---取消上一个勾选框
function OverseaManageMenuSettingDialog:FoodTypeDoSelect()
    if not self.curSlot then return end
    self.foodItemEnv[self.curSlot]:DoSelect()
end

function OverseaManageMenuSettingDialog:RefreshCalculationNode(isAuto)
    self.calculationEnv:SetStatus(true)
    self.calculationEnv:RefreshShowInfo(self.curFood,self.curSelectIndex,isAuto)
    self:RefreshBtnStatus()
end

function OverseaManageMenuSettingDialog:RefreshBtnStatus()
    local needFood = component:GetNeedPutOnFoodCount(self.curSelectIndex)
    if #self.curFood == needFood then
        self.BtnPutOnSwitch.Status = 2
    else
        self.BtnPutOnSwitch.Status = 1
    end
end

return OverseaManageMenuSettingDialog